-- Solitude update 9: starter guides for every Classic dungeon and raid.
-- Paste ALL of this into Supabase → SQL Editor → New query → Run.
-- Safe to run again: it only fills in guides that are missing, and never
-- overwrites tactics your group has written or edited.
-- (Generated by supabase/guides/build_sql.py, edit the .py files and re-run that to change it.)

alter table public.dungeons
  add column if not exists guide_where text,
  add column if not exists guide_overview text,
  add column if not exists guide_before text,
  add column if not exists guide_route jsonb,
  add column if not exists guide_tips text;

-- 'guide' = Solitude's starter guide, 'group' = written or edited by your group
alter table public.boss_notes add column if not exists source text not null default 'group';

create or replace function public.touch_edited()
returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  if auth.uid() is not null and tg_table_name = 'boss_notes' then
    new.updated_by := auth.uid();
    new.source := 'group';   -- once someone edits it, it's your group's
  end if;
  return new;
end; $$;


-- ---------- Ragefire Chasm ----------
insert into public.dungeons (name, kind) values ('Ragefire Chasm', 'dungeon') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Inside Orgrimmar (Cleft of Shadow). Horde only.'),
  guide_overview = coalesce(guide_overview, 'A short first dungeon full of troggs and Searing Blade cultists. A full run takes 20–30 minutes.'),
  guide_before = coalesce(guide_before, 'Pick up the Orgrimmar quests: Searching for the Lost Satchel, Hidden Enemies (chain from Thrall) and Slaying the Beast.'),
  guide_route = coalesce(guide_route, '["Clear the troggs at the start", "Follow the lava path down to Oggleflint and Taragaman", "Continue round to the Searing Blade area for Jergosh and Bazzalan"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Searing Blade cultists cast Curse of Agony: mages and druids can remove it. Watch for patrols on the lava paths.')
where name = 'Ragefire Chasm';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Taragaman the Hungerer', 1, 'Big demon that does a fire nova around himself and uppercuts the tank.', 'Face him away from the group; expect to be knocked back.', 'Keep the tank topped up through the uppercuts.', 'Melee: back off when the fire nova hits if you''re low.'),
  ('Jergosh the Invoker', 2, 'Caster that puts Curse of Weakness and Immolate (a fire DoT) on people.', 'Pull him away from nearby cultists.', 'Remove the curse if you can; heal through the burn.', 'Interrupt his casts.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Ragefire Chasm'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Wailing Caverns ----------
insert into public.dungeons (name, kind) values ('Wailing Caverns', 'dungeon') on conflict (name) do nothing;
