  guide_route = coalesce(guide_route, '["Go down the ramp to Lady Anacondra", "Lord Cobrahn and Lord Pythas in the upper areas", "Kresh wanders the water channels", "Skum and Lord Serpentis through the lower tunnels", "Verdan in the lake area", "Talk to the Disciple of Naralex and escort him, then kill Mutanus"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Druids of the Fang sleep and heal: interrupt them. Deviate Faerie Dragon is a rare spawn. Don''t let the escort NPC die.')
where name = 'Wailing Caverns';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Lady Anacondra', 1, 'Druid caster that puts people to sleep and casts Lightning Bolt.', 'Pull her away from adds.', 'Expect the sleep on you or the tank; be ready to catch up.', 'Interrupt Lightning Bolt and Healing Touch.'),
  ('Kresh', 2, 'Giant turtle that wanders the water. Very simple.', 'Tank and spank.', null, null),
  ('Lord Pythas', 3, 'Druid that casts Sleep, Thunderclap and heals himself.', null, 'Heal through Thunderclap.', 'Interrupt his heals.'),
  ('Lord Cobrahn', 4, 'Druid that turns into a snake and poisons you.', null, 'Cure Poison if you can.', 'Kill his adds quickly if he summons them.'),
  ('Skum', 5, 'Lizard boss in the water with a chain lightning.', 'Stand him near the edge so ranged can spread out.', null, 'Ranged: spread out for Chain Lightning.'),
  ('Lord Serpentis', 6, 'Druid that sleeps a player and casts Lightning Bolt.', null, 'Heal the tank through his melee.', 'Interrupt his heals and bolts.'),
  ('Verdan the Everliving', 7, 'Plant giant that knocks people around with Grasping Vines.', 'Keep him away from the cliff edge.', 'Stay out of melee range.', null),
  ('Mutanus the Devourer', 8, 'Final boss after the Naralex escort. Puts people to sleep and does a big Thundercrack.', 'Grab him fast when he appears.', 'Stay at range; heal through the sleep and stun.', 'Burn him down; he only spawns once the escort is done.'),
  ('Deviate Faerie Dragon', 9, 'Rare spawn, not always there. Can put people to sleep.', null, 'Be ready if someone gets slept.', null)
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Wailing Caverns'
on conflict (dungeon_id, lower(boss)) do nothing;

