-- ---------- Blackrock Depths ----------
insert into public.dungeons (name, kind) values ('Blackrock Depths', 'dungeon') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Blackrock Mountain, between Searing Gorge and Burning Steppes. Go down the chains inside the mountain.'),
  guide_overview = coalesce(guide_overview, 'A huge Dark Iron dwarf city. Too big to clear in one go: groups usually do it in sections (prison, Ring of Law, the bar, then the Emperor). A full run can take 3+ hours.'),
  guide_before = coalesce(guide_before, 'Some doors need keys you earn through quests. The Shadowforge Key opens the way into the city, so ask who in the group has it. There are lots of quests for both factions in Thorium Point, Kargath and Morgan''s Vigil.'),
  guide_route = coalesce(guide_route, '["Detention Block: High Interrogator Gerstahn", "Ring of Law: an arena fight (random boss) then Theldren or the Gladiator event", "Lord Roccor and Houndmaster Grebmar near the start", "Shadowforge Lock to open the city", "Bael''Gar, General Angerforge and Golem Lord Argelmach", "Grim Guzzler bar: Plugger Spazzring, Hurley Blackbreath, Phalanx", "Lord Incendius at the Black Anvil", "Seven Dwarves (Anger''rel, Doom''rel and friends)", "Magmus at the gate, then Emperor Dagran Thaurissan and Princess Moira"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Don''t make the bar angry unless you mean to: if anyone attacks a patron, the whole bar turns on you. Pull carefully in the city, patrols are frequent.')
where name = 'Blackrock Depths';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('High Interrogator Gerstahn', 1, 'Priest in the prison. Uses Shadow Word: Pain and a Psychic Scream fear.', 'Tank her near a wall so feared people don''t run into packs.', 'Dispel Shadow Word: Pain.', 'Interrupt her casts.'),
  ('Lord Roccor', 2, 'Fire elemental in the corridor. Easy.', null, null, null),
  ('Houndmaster Grebmar', 3, 'Dwarf with dogs. Kill the dogs.', 'Grab the dogs.', null, 'Kill the dogs first.'),
  ('Anub''shiah', 4, 'One of the random Ring of Law arena bosses.', null, null, null),
  ('Eviscerator', 5, 'One of the random Ring of Law arena bosses.', null, null, null),
  ('Gorosh the Dervish', 6, 'One of the random Ring of Law arena bosses. Whirlwinds.', 'Stay on him through Whirlwind.', null, 'Melee: step out of Whirlwind.'),
  ('Grizzle', 7, 'One of the random Ring of Law arena bosses. Stomps.', null, null, null),
  ('Hedrum the Creeper', 8, 'One of the random Ring of Law arena bosses. Spider that paralyses.', null, 'Cure poison.', null),
  ('Ok''thor the Breaker', 9, 'One of the random Ring of Law arena bosses. Arcane caster.', null, null, 'Interrupt.'),
  ('Pyromancer Loregrain', 10, 'Fire caster who drops fire totems.', null, null, 'Kill his totems.'),
  ('Warder Stilgiss', 11, 'Frost caster in the vault area.', null, null, 'Interrupt Frost Bolt.'),
  ('Verek', 12, 'Hound that joins near Stilgiss. A normal fight.', null, null, null),
  ('Fineous Darkvire', 13, 'Dwarf architect near the Hall of Crafting. Simple.', null, null, null),
  ('Bael''Gar', 14, 'Giant fire elemental. Summons small fire adds.', 'Grab the adds.', null, 'Kill the adds.'),
  ('Lord Incendius', 15, 'Fire elemental at the Black Anvil. Hits hard with fire.', 'Fire resistance helps.', 'Heavy fire damage on the tank.', null),
  ('General Angerforge', 16, 'Calls lots of adds at around 30% health.', 'Pick up the adds, keep the general on you.', 'Big healing needed when the adds arrive.', 'Save cooldowns for the end; burn him at 30%.'),
  ('Golem Lord Argelmach', 17, 'Golem lord. Wakes up golems around him if you''re not careful.', 'Clear the room first.', null, null),
  ('Ambassador Flamelash', 18, 'Fire elemental who calls small fire adds from the runes.', 'Keep him in the middle.', null, 'Kill the adds before they reach him.'),
  ('Magmus', 19, 'Giant at the gate to the Emperor. Fire jets in the room: stand clear.', 'Tank him away from the fire jets.', null, 'Avoid the fire jets.'),
  ('Panzor the Invincible', 20, 'Rare spawn or optional mob, not always there. A normal fight.', null, null, null),
  ('Plugger Spazzring', 21, 'Bartender in the Grim Guzzler. Only fights if the bar turns on you.', null, null, null),
  ('Hurley Blackbreath', 22, 'Spawns when you steal the Dark Iron Ale. Comes with friends.', 'Grab the adds.', null, null),
  ('Phalanx', 23, 'Golem guard in the bar. Fights after Hurley/Plugger events.', null, null, null),
  ('Anger''rel', 24, 'One of the Seven Dwarves. They come one after another: kill each before the next.', null, 'Long fight: manage mana.', 'Kill each dwarf before the next joins.'),
  ('Doom''rel', 25, 'Leader of the Seven Dwarves. Talk to him to start the fight.', null, null, null),
  ('Princess Moira Bronzebeard', 26, 'Heals the Emperor. Some quests need her left alive, so check before killing her.', 'Keep her off your healer.', null, 'Interrupt her heals on the Emperor.'),
  ('Emperor Dagran Thaurissan', 27, 'Final boss. Hits the tank hard and puts fire on people.', 'Tank him facing away from the group.', 'Heal through the fire damage.', 'Interrupt Moira''s heals so the Emperor goes down.'),
  ('Volida', 28, 'Rare spawn or optional mob, not always there. A normal fight.', null, null, null)
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Blackrock Depths'
on conflict (dungeon_id, lower(boss)) do nothing;

