-- ---------- Upper Blackrock Spire ----------
insert into public.dungeons (name, kind) values ('Upper Blackrock Spire', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Blackrock Mountain, Blackrock Spire. Through the door that needs the Seal of Ascension.'),
  guide_overview = coalesce(guide_overview, 'A 10-player raid dungeon at the top of Blackrock Spire. Dragonkin and Rend Blackhand. Part of the Onyxia attunement for Alliance. Takes 2–2.5 hours.'),
  guide_before = coalesce(guide_before, 'Someone must have the Seal of Ascension (from LBRS). Alliance: get the Onyxia attunement quests from Windsor''s chain. Horde: the Drakkisath chain.'),
  guide_route = coalesce(guide_route, '["Pyroguard Emberseer (break the runes to wake him)", "Solakar Flamewreath in the egg room", "Jed Runewatcher (rare)", "Goraluk Anvilcrack", "Warchief Rend Blackhand and Gyth in the arena", "The Beast", "General Drakkisath at the end"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Lots of dragonkin: tank them facing away. The Rend event has big waves before Rend himself comes.')
where name = 'Upper Blackrock Spire';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
