  ('Jed Runewatcher', 3, 'Rare spawn or optional mob, not always there. A normal fight.', null, null, null),
  ('Goraluk Anvilcrack', 4, 'Blacksmith ogre. Simple.', null, null, null),
  ('Gyth', 5, 'Dragon Rend rides at the start of his fight. Breathes and casts poison.', 'Face Gyth away from the group.', 'Cure poison.', null),
  ('Warchief Rend Blackhand', 6, 'Arena event: waves of orcs and dragons first, then Rend on Gyth, then Rend on foot.', 'Hold the waves; then grab Rend when he dismounts.', 'Long fight: watch mana.', 'Focus the waves, then Gyth, then Rend.'),
  ('The Beast', 7, 'Huge beast that fires a fireball and knocks people away.', 'Tank near a wall.', 'Heavy damage.', 'Stay behind it.'),
