-- ---------- Dire Maul ----------
insert into public.dungeons (name, kind) values ('Dire Maul', 'dungeon') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Feralas, the ruined city in the east. Three wings: East, West and North.'),
  guide_overview = coalesce(guide_overview, 'A ruined elven city with three short wings. North is the famous "tribute run" where you leave the ogres alive for a chest. Each wing takes 30–60 minutes.'),
  guide_before = coalesce(guide_before, 'Get the Crescent Key from the East wing (Pusillin) to open North and West. Grab the Dire Maul quests in Feralas and the libram quests.'),
  guide_route = coalesce(guide_route, '["East: chase Pusillin for the key, then Zevrim Thornhoof, Hydrospawn, Lethtendris, Alzzin the Wildshaper", "West: kill the pylon guards to drop Immol''thar''s shield, then Tendris Warpwood, Magister Kalendris, Illyanna Ravenoak, Immol''thar, Prince Tortheldrin", "North: Guard Mol''dar, Stomper Kreeg, Guard Fengus, Guard Slip''kik, Captain Kromcrush, King Gordok (or the tribute run)"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Tribute run (North): sneak past the guards without killing them and only kill King Gordok. The ogres then give you a big chest. Bring a rogue or mage for the trick.')
where name = 'Dire Maul';
