-- ---------- Stratholme ----------
insert into public.dungeons (name, kind) values ('Stratholme', 'dungeon') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Eastern Plaguelands, north. Main gate (Live side) or Service Entrance (Undead side).'),
  guide_overview = coalesce(guide_overview, 'The burning city. Live side is Scarlet Crusade; Undead side is the Scourge leading to Baron Rivendare. Each side takes 1–1.5 hours.'),
  guide_before = coalesce(guide_before, 'Undead side: get the Key to the City or come in the service entrance. Grab the Postmaster and Ramstein quests. The Baron run has a 45-minute timer for a bonus.'),
  guide_route = coalesce(guide_route, '["Live side: Malor, Cannon Master Willey, Archivist Galford, Grand Crusader Dathrohan (Balnazzar)", "Undead side: Baroness Anastari, Nerub''enkan, Maleki the Pallid, Magistrate Barthilas, Ramstein the Gorger, Baron Rivendare"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Lots of disease and fear. On the Baron run, kill the 3 ziggurat bosses to open his door.')
where name = 'Stratholme';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Hearthsinger Forresten', 1, 'Rare spawn or optional mob, not always there. A normal fight.', null, null, null),
  ('Skul', 2, 'Rare spawn or optional mob, not always there. A normal fight.', null, null, null),
  ('Timmy the Cruel', 3, 'Spawns when you clear his courtyard. Strong but simple.', null, null, null),
  ('Stonespine', 4, 'Rare spawn or optional mob, not always there. A normal fight.', null, null, null),
  ('Postmaster Malown', 5, 'Spawns after you open the mailboxes with keys. Optional.', null, null, null),
  ('The Unforgiven', 6, 'Ghost that freezes people.', null, null, null),
  ('Cannon Master Willey', 7, 'Calls riflemen who shoot the group.', null, null, 'Kill the riflemen.'),
  ('Archivist Galford', 8, 'Fire caster in the library.', null, null, null),
  ('Grand Crusader Dathrohan', 9, 'End of Live side. Turns into Balnazzar at half health.', null, 'Big healing when he changes form.', null),
  ('Baroness Anastari', 10, 'Banshee who mind controls people.', null, null, 'Kill her fast.'),
  ('Nerub''enkan', 11, 'Spider with poison and adds.', null, 'Cure poison.', null),
  ('Maleki the Pallid', 12, 'Frost caster.', null, null, 'Interrupt.'),
  ('Magistrate Barthilas', 13, 'Simple fight in the Undead side.', null, null, null),
  ('Ramstein the Gorger', 14, 'Big abomination that knocks people away.', null, null, null),
  ('Baron Rivendare', 15, 'Final boss. Hits the tank hard and raises skeleton adds.', 'Keep him on you; expect heavy hits.', 'Heavy tank healing.', 'Kill the skeleton adds quickly.'),
  ('Balzaphon', 16, 'Event boss. Optional.', null, null, null)
) as v(boss, position, summary, tank, healer, dps)
