-- ---------- Molten Core ----------
insert into public.dungeons (name, kind) values ('Molten Core', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Blackrock Mountain. Enter through Blackrock Depths (at the Lothos Riftwaker attunement), or swim in from the BRD entrance.'),
  guide_overview = coalesce(guide_overview, 'The first 40-player raid. Fire elementals and core hounds, ending with Ragnaros. A first clear can take a whole evening (3–4 hours).'),
  guide_before = coalesce(guide_before, 'Everyone needs to be attuned (Attunement to the Core: grab a Core Fragment near Lothos in BRD). For Ragnaros, raid members need fire resistance gear, and someone needs Aqual Quintessence to douse the runes. Bring plenty of fire protection potions.'),
  guide_route = coalesce(guide_route, '["Lucifron", "Magmadar", "Gehennas", "Garr", "Shazzrah", "Baron Geddon", "Golemagg the Incinerator", "Sulfuron Harbinger", "Douse the 7 runes (Aqual Quintessence) to summon Majordomo Executus", "Ragnaros"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Lava burns: stay on the path. Core hounds come in packs of 5 and must die within 10 seconds of each other or they revive. Decurse and dispel constantly.')
where name = 'Molten Core';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Lucifron', 1, 'Two Flamewaker Protectors with him mind control people. He curses the raid with Lucifron''s Curse.', 'Three tanks: one on Lucifron, one each on the adds.', 'Remove curses and Impending Doom. Dispel mind control.', 'Kill the two adds first, then Lucifron.'),
  ('Magmadar', 2, 'Big core hound. Fears the raid, enrages, and puts lava pools on the ground.', 'Fear Ward or Tremor Totem on the tank. Tank him away from the raid.', 'Use Fear Ward on the tank; heal through the frenzy.', 'Hunters: Tranquilizing Shot when he frenzies. Everyone move out of the fire.'),
  ('Gehennas', 3, 'Flamewaker with two adds. Curses the raid so healing is weaker. Rains fire.', 'Three tanks: Gehennas and two adds.', 'Remove Gehennas'' Curse as fast as you can.', 'Kill the adds first; move out of Rain of Fire.'),
  ('Garr', 4, 'Big rock elemental with 8 Firesworn adds that explode when killed.', 'Lots of tanks: Garr plus the adds, or warlocks banish some adds.', 'Heal the add tanks.', 'Kill adds one at a time away from the raid. Don''t stand near an add when it dies.'),
  ('Shazzrah', 5, 'Teleports to random people, does Arcane Explosion, curses and counterspells.', 'Reposition quickly after each teleport.', 'Remove curses. Stay spread.', 'Spread out; decurse.'),
  ('Baron Geddon', 6, 'Picks a "Living Bomb" player who explodes after a few seconds. Inferno pulse. Mana-drains casters.', 'Tank him in the middle.', 'Watch for the Living Bomb player and heal them before they explode.', 'If you''re the Living Bomb, RUN out of the raid. Spread out.'),
  ('Golemagg the Incinerator', 7, 'Big giant with two Core Rager dogs. Magma Splash stacks up on his tank, and he Pyroblasts random people.', 'One tank on Golemagg (swap if stacks get high), one on each Core Rager, tanked away from him.', 'Heavy tank healing as Magma Splash stacks.', 'Only kill Golemagg. The Core Ragers can''t be killed while he lives.'),
  ('Sulfuron Harbinger', 8, 'Flamewaker with 4 priest adds that heal each other.', 'Several tanks: Sulfuron plus the 4 priests.', null, 'Kill the 4 priests first, interrupting their heals.'),
  ('Majordomo Executus', 9, 'Comes with 8 adds (4 healers, 4 elites). You win by killing the adds; Majordomo surrenders. He reflects damage and teleports people.', 'Lots of tanks. Watch for Magic Reflection and Damage Shield.', 'Lots of healing on the add tanks.', 'Kill healer adds first. Stop casting when Magic Reflection is up; stop melee when Damage Shield is up.'),
  ('Ragnaros', 10, 'Final boss. Wrath of Ragnaros knocks melee back; Lava Burst hits ranged. After a while he submerges and Sons of Flame come out.', 'Two tanks: one gets knocked back by Wrath, the other picks him up.', 'Fire resistance gear for tanks. Heal through the knockback.', 'Kill the 8 Sons of Flame when he submerges. Melee: watch Wrath of Ragnaros.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Molten Core'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Onyxia's Lair ----------
insert into public.dungeons (name, kind) values ('Onyxia''s Lair', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Dustwallow Marsh, the cave in the far south (Wyrmbog).'),
  guide_overview = coalesce(guide_overview, 'A 40-player raid with one boss: the black dragon Onyxia. About 30–60 minutes once you know the fight.'),
  guide_before = coalesce(guide_before, 'Everyone needs the Drakefire Amulet (Onyxia attunement chain, Alliance from Windsor''s line, Horde from Rexxar''s line). Fire resistance helps the tanks.'),
  guide_route = coalesce(guide_route, '["Clear the whelp eggs carefully at the back of the cave", "Onyxia in the big room"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Never stand in front of her (fire breath) or behind her (tail swipe). Stay away from the whelp cave walls when she''s airborne.')
where name = 'Onyxia''s Lair';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Onyxia', 1, 'Three phases. 1: on the ground; stand at her sides. 2 (65%): she flies, breathes Deep Breath across the room and whelps pour in. 3 (40%): she lands, fears the room, and lava erupts from the floor.', 'Tank her with her head facing the wall, never towards the raid.', 'Fear Ward/Tremor Totem the tank in phase 3. Heal through the eruptions.', 'Phase 2: kill the whelps and move out of her Deep Breath line. Phase 3: avoid the cracks in the floor (lava eruptions), and be ready to get feared.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Onyxia''s Lair'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Blackwing Lair ----------
insert into public.dungeons (name, kind) values ('Blackwing Lair', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Blackrock Mountain, at the very top of Upper Blackrock Spire (attunement by touching the orb behind Drakkisath).'),
  guide_overview = coalesce(guide_overview, 'A 40-player raid for Nefarian and his dragons. Harder than Molten Core. A full clear takes a whole evening.'),
  guide_before = coalesce(guide_before, 'Everyone must be attuned (Blackhand''s Command, from the orb behind General Drakkisath). Bring Onyxia Scale Cloaks for the Nefarian fight.'),
  guide_route = coalesce(guide_route, '["Razorgore the Untamed", "Vaelastrasz the Corrupt", "Broodlord Lashlayer", "Firemaw", "Ebonroc", "Flamegor", "Chromaggus", "Nefarian"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Lots of suppression traps between bosses: rogues can disarm them. Technician packs hit hard.')
where name = 'Blackwing Lair';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Razorgore the Untamed', 1, 'Mind-control Razorgore with the orb to destroy the 30 eggs while the raid holds off waves of adds. Then he fights.', 'Hold the adds at the doors.', 'Lots of add damage on tanks.', 'Kill adds; the mind controller destroys the eggs.'),
  ('Vaelastrasz the Corrupt', 2, 'Starts almost dead but you get a huge mana and energy buff. Burning Adrenaline makes a player explode after 20 seconds.', 'Several tanks in a line: if a tank gets Burning Adrenaline, the next takes over.', 'Infinite mana: heal hard.', 'If you get Burning Adrenaline, run away from the raid. Huge DPS race.'),
  ('Broodlord Lashlayer', 3, 'Hits the tank hard and knocks him away.', 'Two tanks to swap aggro after knockbacks.', 'Heavy tank healing.', 'Don''t pull extra threat after knockbacks.'),
  ('Firemaw', 4, 'Dragon that puts a stacking Flame Buffet on everyone in line of sight.', 'Swap tanks when stacks get high.', 'Heal through Flame Buffet.', 'Hide behind pillars to drop your stacks.'),
  ('Ebonroc', 5, 'Dragon whose Shadow of Ebonroc heals him when he hits that tank.', 'Swap tanks when one gets Shadow of Ebonroc.', null, null),
  ('Flamegor', 6, 'Dragon that frenzies.', 'Face him away from the raid.', null, 'Hunters: Tranquilizing Shot when he frenzies.'),
  ('Chromaggus', 7, 'Dragon with two random breaths each week and a stacking set of debuffs (Brood Afflictions).', 'Tank him so the raid can hide from the breaths behind the doors.', 'Hourglass Sand cures Bronze affliction. Dispel the others.', 'Hide behind the doors when he breathes.'),
  ('Nefarian', 8, 'Phase 1: Lord Victor Nefarius calls drakonid adds. Phase 2: Nefarian lands; class calls hit each class. Phase 3 (20%): skeletons rise.', 'Tank him facing away from the raid (shadowflame).', 'Onyxia Scale Cloaks protect everyone from Shadowflame.', 'Learn your class call. Kill the adds in phase 1 and skeletons in phase 3.'),
  ('Death Talon Wyrmguard', 9, 'Trash before Chromaggus. Has a random vulnerability.', null, null, 'Find its weak school and use it.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Blackwing Lair'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Zul'Gurub ----------
insert into public.dungeons (name, kind) values ('Zul''Gurub', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Northern Stranglethorn Vale, the troll city in the east.'),
  guide_overview = coalesce(guide_overview, 'A 20-player raid of troll high priests and Hakkar the Soulflayer. About 2–3 hours.'),
  guide_before = coalesce(guide_before, 'No attunement. Kill the 4 required high priests to weaken Hakkar. Bring someone who can fish (for Gahz''ranka).'),
  guide_route = coalesce(guide_route, '["High Priestess Jeklik (bats)", "High Priest Venoxis (snakes)", "High Priestess Mar''li (spiders)", "High Priest Thekal (tigers)", "High Priestess Arlokk (panthers)", "Bloodlord Mandokir", "Edge of Madness (one of 4 bosses at random)", "Gahz''ranka (fished up)", "Jin''do the Hexxer", "Hakkar"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Each high priest you kill makes Hakkar weaker. Poison and curse removal are very useful.')
where name = 'Zul''Gurub';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('High Priestess Jeklik', 1, 'Bat priestess. Silences, fears, then throws fire bombs from the air.', 'Move her away from fires.', 'Interrupt her Great Heal.', 'Interrupt the heal; kill bat adds.'),
  ('High Priest Venoxis', 2, 'Snake priest. Holy Wrath and Poison Clouds. Becomes a snake at 50%.', null, 'Cure poison.', 'Interrupt Holy Wrath; avoid clouds.'),
  ('High Priestess Mar''li', 3, 'Spider priestess. Spawns spiders and poisons.', null, 'Cure poison.', 'Kill the spiders quickly.'),
  ('High Priest Thekal', 4, 'Tiger priest with two helpers. All three must die close together.', 'Three tanks.', null, 'Bring all three down evenly.'),
  ('High Priestess Arlokk', 5, 'Panther priestess. Goes stealth and marks a player for panthers.', 'Pick up panthers.', null, 'AoE the panthers.'),
  ('Bloodlord Mandokir', 6, 'Rides a raptor. Watches a player and charges them if they act.', 'Tank both him and the raptor.', null, 'If he says he''s watching you, stop everything.'),
  ('Gri''lek', 7, 'Edge of Madness boss (random each week).', null, null, null),
  ('Hazza''rah', 8, 'Edge of Madness boss (random each week). Makes nightmare illusions.', null, null, 'Kill the illusions.'),
  ('Renataki', 9, 'Edge of Madness boss (random each week). Vanishes and reappears.', null, null, null),
  ('Wushoolay', 10, 'Edge of Madness boss (random each week). Chain lightning.', null, null, 'Spread out.'),
  ('Gahz''ranka', 11, 'Fish him up with a Mudskunk Lure. Knocks people up.', null, null, null),
  ('Jin''do the Hexxer', 12, 'Hexes people, summons shades, and puts brain wash totems down.', null, 'Dispel the hex.', 'Kill the totems first.'),
  ('Hakkar', 13, 'Final boss. Blood Siphon drains the raid and heals him, unless people have Poisonous Blood. Also mind controls. Killing the 4 high priests beforehand removes some of his abilities.', 'Two tanks.', 'Heavy raid healing around Blood Siphon.', 'Before each Blood Siphon, get the Poisonous Blood debuff by killing Sons of Hakkar near you.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Zul''Gurub'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Ruins of Ahn'Qiraj ----------
insert into public.dungeons (name, kind) values ('Ruins of Ahn''Qiraj', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Silithus, the southern gate (opened by the Ahn''Qiraj war effort).'),
  guide_overview = coalesce(guide_overview, 'A 20-player raid of insects and qiraji. Shorter than Zul''Gurub, about 1.5–2 hours.'),
  guide_before = coalesce(guide_before, 'No attunement. Nature resistance helps for some fights.'),
  guide_route = coalesce(guide_route, '["Kurinnaxx", "General Rajaxx (waves)", "Moam", "Buru the Gorger", "Ayamiss the Hunter", "Ossirian the Unscarred"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Lots of silithid trash: AoE them down.')
where name = 'Ruins of Ahn''Qiraj';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Kurinnaxx', 1, 'Mortal Wound stacks on the tank. Sand traps appear.', 'Swap tanks when stacks get high.', null, 'Move off the sand traps.'),
  ('General Rajaxx', 2, 'Waves of qiraji, then Rajaxx himself.', 'Hold each wave.', null, null),
  ('Moam', 3, 'Drains mana from casters, then turns to stone and spawns elementals.', null, 'Manage mana.', 'Burn him fast.'),
  ('Buru the Gorger', 4, 'Chases a player. Kill his eggs next to him to hurt him.', 'Kite him into his eggs.', null, 'Break eggs when Buru is next to them.'),
  ('Ayamiss the Hunter', 5, 'Flying wasp. Lands at 70%.', null, null, 'Ranged DPS do the early work.'),
  ('Ossirian the Unscarred', 6, 'Must be dragged to crystals to change his weakness.', 'Move him between crystals.', null, 'Use his current weakness.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Ruins of Ahn''Qiraj'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Temple of Ahn'Qiraj ----------
insert into public.dungeons (name, kind) values ('Temple of Ahn''Qiraj', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Silithus, the northern gate (opened by the Ahn''Qiraj war effort).'),
  guide_overview = coalesce(guide_overview, 'A 40-player raid ending with C''Thun. One of the hardest raids. Takes several evenings to clear.'),
  guide_before = coalesce(guide_before, 'No attunement. Nature resistance for Huhuran and Viscidus; frost damage for Viscidus.'),
  guide_route = coalesce(guide_route, '["The Prophet Skeram", "The Bug Trio (Vem, Lord Kri, Princess Yauj)", "Battleguard Sartura", "Fankriss the Unyielding", "Viscidus", "Princess Huhuran", "Twin Emperors (Vek''lor and Vek''nilash)", "Ouro", "C''Thun"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Anubisath guards have random abilities. Mind control and silence everywhere.')
where name = 'Temple of Ahn''Qiraj';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('The Prophet Skeram', 1, 'Splits into copies at 75%/50%/25% and mind controls.', 'Tank each copy.', null, 'Find the real Skeram.'),
  ('Vem', 2, 'Part of the Bug Trio. Kill order matters.', null, null, null),
  ('Lord Kri', 3, 'Part of the Bug Trio. Leaves a poison cloud when he dies.', null, null, 'Move away from the cloud.'),
  ('Princess Yauj', 4, 'Part of the Bug Trio. Heals and fears.', null, null, 'Interrupt her heals.'),
  ('Battleguard Sartura', 5, 'Whirlwinds with guard adds.', null, null, 'Kill the adds, then Sartura.'),
  ('Fankriss the Unyielding', 6, 'Spawns worms. Mortal Wound on tanks.', 'Swap tanks.', null, 'Kill the worms.'),
  ('Viscidus', 7, 'Freeze him with frost damage, then shatter with melee.', null, null, 'Use frost spells/wands to freeze him.'),
  ('Princess Huhuran', 8, 'Poisons and goes berserk at 30%.', null, 'Nature resistance helps.', 'Burn her fast.'),
  ('Emperor Vek''lor', 9, 'Twin Emperor (caster). Swaps places with his brother.', 'Warlocks tank Vek''lor.', null, null),
  ('Emperor Vek''nilash', 10, 'Twin Emperor (melee). Swaps places with his brother.', 'Warriors tank Vek''nilash.', null, null),
  ('Ouro', 11, 'Giant sandworm. Submerges and resurfaces under people.', null, null, 'Move when he burrows.'),
  ('C''Thun', 12, 'Final boss. Eye beams and tentacles; then you go inside his stomach.', 'Spread out in a circle.', null, 'Kill tentacles.'),
  ('Merithra of the Dream', 13, 'Not a regular boss in the temple. You can ignore this entry.', null, null, null)
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Temple of Ahn''Qiraj'
on conflict (dungeon_id, lower(boss)) do nothing;

-- ---------- Naxxramas ----------
insert into public.dungeons (name, kind) values ('Naxxramas', 'raid') on conflict (name) do nothing;
update public.dungeons set
  guide_where = coalesce(guide_where, 'Floating necropolis over Eastern Plaguelands (entrance at Light''s Hope Chapel).'),
  guide_overview = coalesce(guide_overview, 'The hardest Classic raid. Four wings (Arachnid, Plague, Military, Construct), then Frostwyrm Lair. Weeks of progress for most guilds.'),
  guide_before = coalesce(guide_before, 'Attunement from the Argent Dawn at Light''s Hope. Frost resistance for Sapphiron.'),
  guide_route = coalesce(guide_route, '["Arachnid Quarter: Anub''Rekhan, Grand Widow Faerlina, Maexxna", "Plague Quarter: Noth the Plaguebringer, Heigan the Unclean, Loatheb", "Military Quarter: Instructor Razuvious, Gothik the Harvester, The Four Horsemen", "Construct Quarter: Patchwerk, Grobbulus, Gluth, Thaddius", "Frostwyrm Lair: Sapphiron, Kel''Thuzad"]'::jsonb),
  guide_tips = coalesce(guide_tips, 'Each wing ends with a teleporter back to the entrance. Consumables are essential.')
where name = 'Naxxramas';
insert into public.boss_notes (dungeon_id, boss, position, summary, tank, healer, dps, source, updated_by)
select d.id, v.boss, v.position, v.summary, v.tank, v.healer, v.dps, 'guide', null
from public.dungeons d, (values
  ('Anub''Rekhan', 1, 'Locust Swarm: kite him around the room.', 'Kite during Locust Swarm.', null, null),
  ('Grand Widow Faerlina', 2, 'Enrages. Priests mind control her worshippers to stop it.', null, null, null),
  ('Maexxna', 3, 'Webs players to the wall and spawns spiderlings.', null, null, 'Free webbed players.'),
  ('Noth the Plaguebringer', 4, 'Teleports to the balcony and spawns skeletons.', null, 'Remove curses.', null),
  ('Heigan the Unclean', 5, 'The "safety dance": the floor erupts in moving waves.', null, null, 'Follow the safe zones.'),
  ('Loatheb', 6, 'Healing only possible every few seconds; spores give crit.', null, 'Coordinate healing windows.', 'Stand in spores for crits.'),
  ('Instructor Razuvious', 7, 'Priests mind control his students to tank him.', 'Priests MC students.', null, null),
  ('Gothik the Harvester', 8, 'Waves of adds on both sides of the room.', null, null, null),
  ('The Four Horsemen', 9, 'Four horsemen, each with stacking marks. Tanks rotate between them.', 'Rotate between horsemen.', null, null),
  ('Patchwerk', 10, 'Tank-and-spank DPS race. Hateful Strike hits high-health tanks.', 'Three tanks topped up.', 'Heavy tank healing.', 'Pure DPS race.'),
  ('Grobbulus', 11, 'Injects players who leave poison clouds.', null, null, 'If injected, move away.'),
  ('Gluth', 12, 'Eats zombies to heal; frenzies.', null, null, 'Kite and kill zombies.'),
  ('Thaddius', 13, 'Polarity shift: positive and negative charges.', null, null, 'Stand with your charge.'),
  ('Sapphiron', 14, 'Frost dragon. Ice blocks players.', null, 'Frost resistance.', 'Hide behind ice blocks during Frost Breath.'),
  ('Kel''Thuzad', 15, 'Final boss. Waves of adds, then Kel''Thuzad.', null, null, 'Interrupt Frostbolt.')
) as v(boss, position, summary, tank, healer, dps)
where d.name = 'Naxxramas'
on conflict (dungeon_id, lower(boss)) do nothing;
